#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""ТІЛЬКИ ЧИТАННЯ. Що є в базі по руху грошей з трьох гривневих рахунків з 01.05.2026."""
import collections, os, sys, urllib.parse
BASE = "/root/unitex-finrep"
sys.path.insert(0, os.path.join(BASE, "engine"))
os.chdir(BASE)
from odata_client import ODataClient
c = ODataClient()
ACCS = ["Банк Юнітекс Ейч-Ді", "Банк Юнітекс Ейч-Ді Восток", "Банк Юнітекс Форвардинг"]
FROM = "2026-05-01"

def get(p): return c._get(urllib.parse.quote(p, safe="/?&=$,'"))

def page(ent, sel=None):
    out, skip = [], 0
    while True:
        p = "/%s?$format=json&$top=1000&$skip=%d" % (ent, skip)
        if sel: p += "&$select=" + ",".join(sel)
        b = get(p)["value"]; out += b
        if len(b) < 1000: return out
        skip += 1000

def blank(x): return (not x) or str(x).startswith("00000000-0000")
def d10(x):
    x = str(x or ""); return "" if (not x or x.startswith("0001-01-01")) else x[:10]
def f(x):
    try: return float(x or 0)
    except (TypeError, ValueError): return 0.0
def nm(e):
    return {r["Ref_Key"]: (r.get("Description") or "").strip()
            for r in page(e, ["Ref_Key", "Description"])}

acc = nm("Catalog_ВидОплаты"); art = nm("Catalog_СтатьиСчета")
ctr = nm("Catalog_Контрагенты"); cli = nm("Catalog_Клиенты")
deal = {r["Ref_Key"]: (r.get("Number") or "").lstrip("0")
        for r in page("Document_Сделка", ["Ref_Key", "Number"])}
rn = {r["Ref_Key"]: r for r in page("Document_РасходнаяНакладная",
      ["Ref_Key", "Number", "Сделка_Key", "Услуга_Key", "Контрагент_Key"])}

lines = collections.defaultdict(list)
for r in page("Document_СписаниеДенСредств_Счета"):
    lines[r["Ref_Key"]].append(r)

sd = page("Document_СписаниеДенСредств")
print("=== СПИСАННЯ КОШТІВ з 01.05.2026, по рахунках ===")
tot = collections.Counter(); cnt = collections.Counter()
noline = collections.Counter(); nodeal = collections.Counter()
for h in sd:
    if not h.get("Posted") or h.get("DeletionMark"): continue
    a = acc.get(h.get("ВидОплаты_Key"), "")
    if a not in ACCS or d10(h.get("Date")) < FROM: continue
    cnt[a] += 1
    tot[a] += f(h.get("Сумма_УЕ"))
    ls = lines.get(h["Ref_Key"], [])
    if not ls:
        noline[a] += 1
    for ln in ls:
        t = rn.get(ln.get("Счет"))
        if not t:
            nodeal["%s | %s" % (a, (ln.get("Счет_Type") or "").split("_")[-1])] += 1
        elif blank(t.get("Сделка_Key")):
            nodeal["%s | витратна без угоди" % a] += 1
for a in ACCS:
    print("  %-30s %3d док., %12.2f УО, без рядків-розшифровки: %d"
          % (a, cnt[a], tot[a], noline[a]))
print("  рядки, які НЕ ведуть на угоду:")
for k, n in nodeal.most_common():
    print("     %-60s %d" % (k, n))

print("\n=== ВНУТРІШНІ ПЕРЕМІЩЕННЯ з 01.05.2026 (тут угоди немає взагалі) ===")
vp = [r for r in page("Document_ВнутреннееПеремещение")
      if r.get("Posted") and not r.get("DeletionMark") and d10(r.get("Date")) >= FROM]
print("  документів:", len(vp))
pairs = collections.Counter(); sums = collections.Counter()
for r in vp:
    k = "%s → %s" % (acc.get(r.get("ВидОплаты_Key"), "?"), acc.get(r.get("ВидОплаты2_Key"), "?"))
    pairs[k] += 1; sums[k] += f(r.get("Сумма"))
for k, n in pairs.most_common():
    print("     %-58s %3d док.  %14.2f (валюта рахунку)" % (k, n, sums[k]))

print("\n=== ПРИХОД (гроші від клієнта) з 01.05.2026 ===")
pl = collections.defaultdict(list)
for r in page("Document_Приход_Счета"): pl[r["Ref_Key"]].append(r)
pr = [r for r in page("Document_Приход")
      if r.get("Posted") and not r.get("DeletionMark") and d10(r.get("Date")) >= FROM]
byacc = collections.Counter(); bys = collections.Counter(); withdeal = 0
for h in pr:
    a = acc.get(h.get("ВидОплаты_Key"), "?")
    byacc[a] += 1; bys[a] += f(h.get("Сумма_УЕ"))
    if any(not blank(x.get("Сделка_Key")) for x in pl.get(h["Ref_Key"], [])): withdeal += 1
print("  документів: %d, з них з прив'язкою до угоди: %d" % (len(pr), withdeal))
for k, n in byacc.most_common():
    print("     %-30s %3d док.  %12.2f УО" % (k, n, bys[k]))
PYEOF
python3 /root/lc_flow.py > /root/lc_flow.txt 2>&1; sed -n '1,12p' /root/lc_flow.txt
